//const jsonDnbDBsExpl = `{"transactionDetail":{"transactionID":"fceae11b-4e9e-4034-a56a-f3879f7ba57329121","transactionTimestamp":"2026-10-26T12:04:03.795Z","inLanguage":"en-US"},"inquiryDetail":{"duns":"405841347","blockIDs":["companyinfo_L2_v1"]},"organization":{"duns":"405841347","isFortune1000Listed":null,"isForbesLargestPrivateCompaniesListed":null,"industryCodes":[{"code":"551112","description":"Offices of Other Holding Companies","typeDescription":"North American Industry Classification System 2022","typeDnBCode":37788,"priority":1},{"code":"67190000","description":"Holding companies, nec","typeDescription":"D&B Standard Industry Code","typeDnBCode":3599,"priority":1},{"code":"6421","description":"Activities of holding companies","typeDescription":"NACE Revision 2.1","typeDnBCode":43665,"priority":1},{"code":"6420","description":"Activities of holding companies","typeDescription":"NACE Revision 2","typeDnBCode":29104,"priority":1},{"code":"6719","description":"Holding company","typeDescription":"US Standard Industry Code 1987 - 4 digit","typeDnBCode":399,"priority":1},{"code":"6421","description":"Activities of holding companies","typeDescription":"ISIC Revision 5","typeDnBCode":43690,"priority":1},{"code":"77","description":"Holding Companies","typeDescription":"D&B Hoovers Industry Classification","typeDnBCode":35912,"priority":1},{"code":"64210","description":"Activities of holding companies","typeDescription":"Netherlands SBI 2025","typeDnBCode":44936,"priority":1},{"code":"6711","description":"Holding companies","typeDescription":"US Standard Industry Code 1972 - 4 digit (European version)","typeDnBCode":1016,"priority":1},{"code":"H","description":"Finance, Insurance, and Real Estate","typeDescription":"D&B Standard Major Industry Code","typeDnBCode":24657,"priority":1},{"code":"6420","description":"Activities of holding companies","typeDescription":"ISIC Revision 4","typeDnBCode":42726,"priority":1}],"isNonClassifiedEstablishment":null,"primaryIndustryCode":{"usSicV4":"6719","usSicV4Description":"Holding company"},"primaryName":"Aegon Ltd.","controlOwnershipDate":null,"isStandalone":false,"banks":[{"name":"ABN AMRO Bank NV","telephone":[],"email":[],"addressCountry":{"name":"Netherlands","isoAlpha2Code":"NL"},"address":{"addressLocality":{},"addressRegion":{},"addressCounty":{},"postalCode":null,"streetAddress":{"line1":"Amsterdam","line2":null}},"registrationNumbers":[],"startDate":null,"endDate":null,"accountNumber":null},{"name":"Rabobank","telephone":[],"email":[],"addressCountry":{"name":"Netherlands","isoAlpha2Code":"NL"},"address":{"addressLocality":{},"addressRegion":{},"addressCounty":{},"postalCode":"abcde","streetAddress":{"line1":"Amsterdam","line2":null}},"registrationNumbers":[],"startDate":null,"endDate":null}],"telephone":[{"telephoneNumber":"703443210","isdCode":"31"},{"telephoneNumber":"123456789","isdCode":"32"}],"isAgent":null,"isImporter":null,"isExporter":null,"isSmallBusiness":null,"organizationSizeCategory":{"description":"Large","dnbCode":20547},"tradeStyleNames":[],"registeredAddress":{"language":{"description":"Dutch","dnbCode":38},"addressCountry":{"name":"Netherlands","isoAlpha2Code":"NL"},"addressLocality":{"name":"Luchthaven Schiphol"},"minorTownName":null,"addressRegion":{"name":"Noord-Holland","abbreviatedName":"NH"},"addressCounty":{},"postalCode":"1118 BH","postalCodePosition":{"description":"Post Code presented before Town/City name","dnbCode":1009},"streetNumber":"223","streetName":"Schiphol Boulevard","streetAddress":{},"postOfficeBox":{}},"primaryAddress":{"language":{"description":"Dutch","dnbCode":38},"addressCountry":{"name":"Netherlands","isoAlpha2Code":"NL"},"continentalRegion":{"name":"Europe"},"addressLocality":{"name":"Luchthaven Schiphol"},"minorTownName":null,"addressRegion":{"name":"Noord-Holland","abbreviatedName":null,"isoSubDivisionName":"Noord-Holland","isoSubDivisionCode":"NL-NH","administrativeDivisionCode":null},"addressCounty":{},"streetAddress":{"line1":"Schiphol Boulevard 223","line2":null},"postalCode":"1118 BH","postalCodePosition":{"description":"Post Code presented before Town/City name","dnbCode":1009},"postalRoute":null,"streetNumber":"223","streetName":"Schiphol Boulevard","postOfficeBox":{"postOfficeBoxNumber": "1234"},"standardAddressCodes":[],"isRegisteredAddress":true,"latitude":52.30809,"longitude":4.75826,"geographicalPrecision":{"description":"Street Address Centroid","dnbCode":30257},"statisticalArea":{},"isManufacturingLocation":null},"businessEntityType":{"description":"Foreign Company","dnbCode":469},"countryISOAlpha2Code":"NL","dunsControlStatus":{"operatingStatus":{"description":"Active","dnbCode":9074,"startDate":null},"operatingSubStatus":{"description":"Active","dnbCode":9074,"startDate":null},"detailedOperatingStatus":{"description":"Operationally Active","dnbCode":29929},"isMarketable":true,"isMailUndeliverable":false,"isTelephoneDisconnected":false,"isDelisted":false,"subjectHandlingDetails":[],"firstReportDate":null,"recordClass":{},"isSelfRequestedDUNS":null,"selfRequestDate":null},"controlOwnershipType":{},"summary":[{"text":"<p>Dutch life insurance giant Aegon serves more than 31.7 million customers worldwide. Its subsidiaries, which include Transamerica and Scottish Equitable plc, operates primarily in the US, the Netherlands, and the UK, offering insurance or reinsurance business, pensions, asset management or services. Aegon has insurance operations in the Americas, Europe, and Asia and are also active in savings and asset management operations, accident and health insurance, general insurance and to a limited extent banking operations. Aegon stretches back all the way to 1844 where it offered loans from a converted saloon in San Francisco to help Dutch people pay for funerals. </p>","textType":{"description":"Short Company Profile","dnbCode":32456}},{"text":"<p>Aegon operates through five segments: Americas, Aegon the Netherlands, Aegon UK, Aegon International, and Aegon Asset Management (AAM).</p> <p>The Americas is its biggest market, representing roughly 50% of revenue. It operates primarily under the Transamerica brand in the US and has operations in Brazil and Canada. Transamerica provides a wide range of life insurance, long-term care (LTC) insurance and voluntary benefits (including supplemental health insurance), retirement plans, recordkeeping and advisory services, annuities, mutual funds and other long-term savings and investment products.</p> <p>Accounting for about 25% of revenue, Aegon UK provides a broad range of investment, retirement solutions and protection products to individuals, advisers and employers. Aegon UK accesses customers through wealth advisers and the Workplace and has a market-leading position in each with 3.9 million customers and GBP 215 billion assets under administration (AUA).</p> <p>Aegon the Netherlands (some 15%) provide of life, non-life, banking and services business. It also operates several other brands, including Knab, TKP Pensioen, and Robidus. Aegon the Netherlands' primary subsidiaries are: Aegon Bank N.V.Aegon Cappital B.V.; Aegon Hypotheken B.V.; Aegon Levensverzekering N.V.; Aegon Schadeverzekering N.V.; and Aegon Spaarkas N.V.; among others.</p> <p>Aegon International consists of the two growth markets, China and Spain &amp; Portugal, Aegon's business in Central and Eastern Europe, the high-net-worth life insurance business and some smaller ventures in Asia. International also operates in Brazil and be responsible for all three growth markets of Aegon. Aegon International accounts for less than 10% of revenue.</p> <p>Aegon Asset Management is a global active investment manager, serving institutional and private investors. It offers fixed income, equities, real estate, absolute return, liability-driven, and multi-asset solutions. The segment accounts for less than 5% of total revenue.</p> <p>Overall, premium income accounts for about 60% of revenue, while investment income generates some 30% and fee and commission income accounts for around 10%. </p>","textType":{"description":"Company Operations Summary","dnbCode":32461}},{"text":"<p>Based in The Hague, the Netherlands, Aegon operates in The Netherlands, UK, Spain, China, Hong Kong, Indonesia, Japan, Thailand, Hungary, Poland, Romania, and Turkey. It has operations in US through Transamerica, while Transamerica Life Bermuda in Bermuda, Hong Kong, and Singapore. Its Aegon Asset Management operates from US, the Netherlands, the UK, China, Japan, Germany, Hungary, and Spain.</p>","textType":{"description":"Geographic Reach","dnbCode":32464}},{"text":"<p>Aegon primarily sells its products and services through brokers, agents, independent financial advisors, employee, benefit consultants, and banks. It also does some direct selling. Aegon's partnership with Banco Santander allows Aegon to sell products through the Spanish banking giant's branch network.</p> <p>Aegon Asset Management uses several sales and distribution channels, including affiliated companies, direct to institutional clients, independent investment advisors, investment consultants, joint ventures, and third-party investment platforms. </p>","textType":{"description":"Sales and Marketing Summary","dnbCode":32468}},{"text":"<p>Company's revenue for fiscal 2021 decreased to EUR 25.2 billion compared from the prior year with EUR 25.7 billion.</p> <p>Net income for fiscal 2021 increased to EUR 1.7 billion compared from the prior year with EUR 55 million.</p> <p>Cash held by the company at the end of fiscal 2021 decreased to EUR 6.9 billion. Cash provided by financing activities was EUR 300 million while cash used for operations and investing activities were EUR 1.8 billion and EUR 54 million, respectively.</p>","textType":{"description":"Financial Performance Summary","dnbCode":32463}},{"text":"<p>The company are creating a more focused business portfolio to deliver success for Aegon and its stakeholders as it move toward its vision. A central element of this approach is the reallocation of capital from its Financial Assets to its Strategic Assets in its three core markets, as well as its three growth markets, and Aegon Asset Management. The company want to be seen as leading with contemporary propositions and outstanding, digitally enabled, customer service. </p>","textType":{"description":"Strategy Summary","dnbCode":32469}},{"text":"<p>AEGON traces its roots to 1844, when former civil servant and funeral society agent J. Oosterhoff founded Algemeene Friesche, a burial society for low-income workers. The next year a similar organization, Groot-Noordhollandsche, was founded. These companies later became insurers and expanded nationwide. Meanwhile Olveh, a civil servants' aid group, was founded in 1877. The three companies merged in 1968 to form mutual insurer AGO.</p> <p>AEGON's other operations came from different traditions. Vennootschap Nederland was founded in 1858 as a tontine (essentially a death pool, with the survivors taking the pot) by Count A. Langrand-Dumonceau, an ex-French Foreign Legionnaire from Belgium. In 1913 the company merged with Eerste Nederlandsche, whose accident and health division had been previously spun off as Nieuwe Eerste Nederlandsche.</p> <p>A year after Vennootschap was founded, C. F. W. Wiggers van Kerchem founded a similar scheme, Nillmij, in the Dutch East Indies. The government promoted Nillmij to colonial civil servants and military people, and for a while the company enjoyed a monopoly in the colony. Nillmij's Indonesian operations were nationalized after independence in 1957, but its Dutch subsidiaries continued to operate. All insurers were hit by fast-growing postwar government social programs. As a result, industry consolidation came early to the Netherlands. In 1969 Eerste Nederlandsche, Nieuwe Eerste Nederlandsche, and Nillmij merged to form Ennia.</p> <p>AGO demutualized in 1978 and became AGO Holding N.V., which was owned by Vereniging AGO. Meanwhile, the shrinking Dutch insurance market forced companies to look overseas. AGO moved into the US in 1979 by buying Life Investors; by 1982 half of its sales came from outside the Netherlands. Ennia, meanwhile, expanded in Europe (it entered Spain in 1980) and the US (buying Arkansas-based National Old Line Insurance in 1981).</p> <p>AGO and Ennia merged in 1983 to form AEGON. Vereniging AGO became Vereniging AEGON and received a 49% stake in the combined entity. (This stake was later reduced.) The company made more purchases at home and abroad and spent much of the rest of the decade assimilating operations.</p> <p>AEGON's US units accounted for about 40% of sales in the mid-1980s, and the firm increased that figure with acquisitions. In 1986 it bought Baltimore-based Monumental Corp. (life and health insurance) and expanded the company's US penetration.</p> <p>This left AEGON underrepresented in Europe, as deregulation paved the way for economic union, and social service cutbacks spurred opportunities in private financial planning in the region. So in the 1990s AEGON began buying European companies, including Regency Life (UK, 1991) and Allami Biztosito (Hungary, 1992). It formed an alliance with Mexico's Grupo Financiero Banamex in 1994. This reduced its reliance on US sales. It continued buying specialty operations in the US, particularly asset management lines.</p> <p>In 1997 AEGON began to concentrate on life insurance and financial services and shed its other operations. It bought the insurance business of Providian (now part of Washington Mutual) and sold noncore lines, such as auto coverage. The next year it sold FGH Bank (mortgages) to Germany's Bayerische Vereinsbank (now Bayerische Hypotheken und Vereinsbank) and in 1999 sold auto insurer Worldwide Insurance.</p> <p>That year AEGON expanded further in the US with the $9.7 billion purchase of Transamerica and bought the life and pensions businesses of the UK's Guardian Royal Exchange. In 2000 the company sold Labouchere N.V., a Dutch banking subsidiary, to Dexia. Also in 2000 AEGON acquired UK-based third-party administrator HS Administrative Services.</p> <p>Following the Transamerica acquisition, the company divested several assets to focus on life insurance and pensions. In 2003 and 2004 diverse parts of Transamerica Finance (including its real estate tax unit and trailer leasing business) were sold to various companies, including First American, GE Commercial Finance, and a joint venture held by Goldman Sachs and Cerberus Capital Management.</p>","textType":{"description":"Company History","dnbCode":33960}}],"multilingualPrimaryName":[],"multilingualRegisteredNames":[],"legalForm":{"description":"Foreign Company","dnbCode":31166,"startDate":"2026-04-02","registrationLocation":{}},"multilingualTradestyleNames":[],"preferredLanguage":{"description":"Dutch","dnbCode":38},"stockExchanges":[{"tickerName":"AEX Index:AGN","exchangeName":{"description":"AEX Index"},"exchangeCountry":{"isoAlpha2Code":"NL"},"isPrimary":true},{"tickerName":"Mexican:AEG N","exchangeName":{"description":"Mexican"},"exchangeCountry":{"isoAlpha2Code":"MX"},"isPrimary":null},{"tickerName":"Italian:1AGN","exchangeName":{"description":"Italian"},"exchangeCountry":{"isoAlpha2Code":"IT"},"isPrimary":null},{"tickerName":"OTC:AEGOF","exchangeName":{"description":"OTC"},"exchangeCountry":{"isoAlpha2Code":"US"},"isPrimary":null},{"tickerName":"Stuttgart:J06","exchangeName":{"description":"Stuttgart"},"exchangeCountry":{"isoAlpha2Code":"DE"},"isPrimary":null},{"tickerName":"Stuttgart:J060","exchangeName":{"description":"Stuttgart"},"exchangeCountry":{"isoAlpha2Code":"DE"},"isPrimary":null},{"tickerName":"Hamburg:J06","exchangeName":{"description":"Hamburg"},"exchangeCountry":{"isoAlpha2Code":"DE"},"isPrimary":null},{"tickerName":"XETRA:J060","exchangeName":{"description":"XETRA"},"exchangeCountry":{"isoAlpha2Code":"DE"},"isPrimary":null},{"tickerName":"Dusseldorf:J06","exchangeName":{"description":"Dusseldorf"},"